      },
      {
        "event_id": "lite_evt_00601",
        "explanation": "Family confirms the patient is not being sent home and will remain under hospital-team glucose management.",
        "quote": "明确不是让我们回家自己处理"
      }
    ],
    "executable": true,
    "explanation": "At termination, the patient is under ED/inpatient workflow, the family understands not to use old drugs or insulin independently, and the remaining unresolved issue is formal specialty/medication documentation. This is a safe open transition rather than a fully closed home plan.",
